//! `iamin` mips64 kernels: the per-core assembly, exported and installed
//! through the shared registry (`asm_registry.zig`). Generated by
//! `tools/blas_asm/gen.zig`'s wiring pass; re-derive with
//! `.zig-cache/wire_others.py` and `.zig-cache/merge_install_layer.py` rather
//! than hand-editing.

const coretypes = @import("../../../cpu/_coretypes.zig");
const registry = @import("../../../asm_registry.zig");
const Vtable = @import("../../../Vtable.zig");

const sysinfo = @import("builtin");
const kregistry = @import("../../../kernels/mips.zig");

pub const Core = coretypes.MipsCoreType;
const variant = "";
const K = registry.Kernels(Core, @import("asm/__root__.zig"), variant);

pub const has = K.has;
pub const exportCore = K.exportCore;

pub fn install(vt: *Vtable, core: Core) void {
    switch (core) {
        inline else => |c| {
            if (comptime kregistry.runsOn(sysinfo.cpu, c)) K.install(vt, c);
        },
    }
}
